        tableRowHeight = 48.dp,
        cardInset = 28.dp,
        sectionGap = 28.dp,
        fieldGap = 16.dp,
    )

    val CompactDensity: SyntaraDensityTokens = SyntaraDensityTokens(
        controlHeight = 32.dp,
        controlPaddingInline = 12.dp,
        tableRowHeight = 40.dp,
        cardInset = 20.dp,
        sectionGap = 20.dp,
        fieldGap = 12.dp,
    )

    val Space: SyntaraSpace = SyntaraSpace(
        x0 = 0.dp,
        x1 = 4.dp,
        x2 = 8.dp,
        x3 = 12.dp,
        x4 = 16.dp,
        x5 = 20.dp,
        x6 = 24.dp,
        x8 = 32.dp,
        x10 = 40.dp,
        x12 = 48.dp,
        x16 = 64.dp,
    )

    val Radius: SyntaraRadius = SyntaraRadius(
        button = 8.dp,
        field = 8.dp,
        container = 12.dp,
        badge = 6.dp,
        pill = 9999.dp,
    )

    val FontFamilies: SyntaraFontFamilies = SyntaraFontFamilies(
        heading = listOf("Inter Tight", "Inter"),
        body = listOf("Inter"),
        mono = listOf("JetBrains Mono"),
    )

    val FontSizes: SyntaraFontSizes = SyntaraFontSizes(
        xs = 12.sp,
        sm = 13.sp,
        md = 14.sp,
        lg = 16.sp,
        xl = 20.sp,
        xl2 = 24.sp,
        xl3 = 32.sp,
        xl4 = 40.sp,
        xl5 = 48.sp,
    )

    val FontWeights: SyntaraFontWeights = SyntaraFontWeights(
        regular = FontWeight(400),
        medium = FontWeight(500),
        semibold = FontWeight(600),
        bold = FontWeight(700),
    )

    val LineHeights: SyntaraLineHeights = SyntaraLineHeights(
        tight = 1.2.em,
        snug = 1.35.em,
        normal = 1.5.em,
    )

    val Tracking: SyntaraTracking = SyntaraTracking(
        heading = (-0.01).em,
        xs = 0.em,
        sm = (-0.003).em,
        md = (-0.006).em,
        lg = (-0.011).em,
        xl = (-0.017).em,
        xl2 = (-0.019).em,
        xl3 = (-0.022).em,
        xl4 = (-0.022).em,
        xl5 = (-0.022).em,
        caps = 0.08.em,
    )

    val Motion: SyntaraMotion = SyntaraMotion(
        durationFast = 120,
        durationNormal = 200,
        durationSlow = 320,
        durationSpring = 402,
        easing = CubicBezierEasing(0.2f, 0f, 0f, 1f),
        easingOut = CubicBezierEasing(0.16f, 1f, 0.3f, 1f),
    )

    val Spring: SyntaraSpring = SyntaraSpring(
        mass = 1f,
        stiffness = 400f,
        damping = 28f,
    )

    val Icon: SyntaraIcon = SyntaraIcon(
        stroke = 1.5f,
    )

    fun colors(darkTheme: Boolean): SyntaraColors = if (darkTheme) DarkColors else LightColors

    fun effects(darkTheme: Boolean): SyntaraEffects = if (darkTheme) DarkEffects else LightEffects

    fun density(density: SyntaraDensity): SyntaraDensityTokens = when (density) {
        SyntaraDensity.Comfortable -> ComfortableDensity
        SyntaraDensity.Compact -> CompactDensity
    }
}

val LocalSyntaraColors = staticCompositionLocalOf<SyntaraColors> {
    error("No SyntaraColors provided. Wrap your content in SyntaraTheme { }.")
}

val LocalSyntaraEffects = staticCompositionLocalOf<SyntaraEffects> {
    error("No SyntaraEffects provided. Wrap your content in SyntaraTheme { }.")
}

val LocalSyntaraDensityTokens = staticCompositionLocalOf<SyntaraDensityTokens> {
    error("No SyntaraDensityTokens provided. Wrap your content in SyntaraTheme { }.")
}

/**
 * Provides the scheme- and density-dependent Syntara tokens to [content]. Read them through SyntaraTheme:
 *
 * ```
 * SyntaraTheme {
 *     Text("Hi", color = SyntaraTheme.colors.textDefault, fontSize = SyntaraTheme.fontSize.md)
 * }
 * ```
 */
@Composable
fun SyntaraTheme(
    darkTheme: Boolean = isSystemInDarkTheme(),
    density: SyntaraDensity = SyntaraTokens.DefaultDensity,
    content: @Composable () -> Unit,
) {
    CompositionLocalProvider(
        LocalSyntaraColors provides SyntaraTokens.colors(darkTheme),
        LocalSyntaraEffects provides SyntaraTokens.effects(darkTheme),
        LocalSyntaraDensityTokens provides SyntaraTokens.density(density),
        content = content,
    )
}

/**
 * Syntara tokens for the current composition. Scheme and density values need a SyntaraTheme { }
 * above them.
 */
object SyntaraTheme {
    val colors: SyntaraColors
        @Composable @ReadOnlyComposable get() = LocalSyntaraColors.current

    val effects: SyntaraEffects
        @Composable @ReadOnlyComposable get() = LocalSyntaraEffects.current

    val density: SyntaraDensityTokens
        @Composable @ReadOnlyComposable get() = LocalSyntaraDensityTokens.current

    val space: SyntaraSpace get() = SyntaraTokens.Space
    val radius: SyntaraRadius get() = SyntaraTokens.Radius
    val fontFamily: SyntaraFontFamilies get() = SyntaraTokens.FontFamilies
    val fontSize: SyntaraFontSizes get() = SyntaraTokens.FontSizes
    val fontWeight: SyntaraFontWeights get() = SyntaraTokens.FontWeights
    val lineHeight: SyntaraLineHeights get() = SyntaraTokens.LineHeights
    val tracking: SyntaraTracking get() = SyntaraTokens.Tracking
    val motion: SyntaraMotion get() = SyntaraTokens.Motion
    val spring: SyntaraSpring get() = SyntaraTokens.Spring
    val icon: SyntaraIcon get() = SyntaraTokens.Icon
}
